import { useEffect, useState } from 'react'
import { Boxes, RefreshCw } from 'lucide-react'
import { catalogApi, inventoryApi, type InventoryBatch, type Product, type Vendor } from '../../api'
import { Button } from '../../components/ui/button'
import { Card, CardContent } from '../../components/ui/card'
import { Input } from '../../components/ui/input'

export function InventoryPage({ vendor, storeId }: { vendor?: Vendor; storeId?: number }) { const [batches, setBatches] = useState<InventoryBatch[]>([]); const [products, setProducts] = useState<Product[]>([]); const [productId, setProductId] = useState(''); const [quantity, setQuantity] = useState(''); const [cost, setCost] = useState(''); const [expiration, setExpiration] = useState(''); const [message, setMessage] = useState(''); const load = () => { if (vendor && storeId) inventoryApi.list(vendor.id, storeId).then(setBatches).catch(() => setBatches([])) }; useEffect(() => { load(); if (vendor) catalogApi.products(vendor.id).then(setProducts).catch(() => setProducts([])) }, [vendor, storeId]); async function receive() { if (!vendor || !storeId || !productId || !quantity || !cost) return; try { await inventoryApi.receive(vendor.id, storeId, Number(productId), Number(quantity), Number(cost), expiration || undefined); setMessage('Stock received successfully.'); setQuantity(''); setCost(''); setExpiration(''); load() } catch (error) { setMessage(error instanceof Error ? error.message : 'Unable to receive stock.') } } return <><PageIntro title="Inventory" text="Receive stock, track batches, monitor expiration, and adjust quantities for the selected store." />{message && <p className="mb-4 rounded-xl bg-indigo-50 p-3 text-sm font-semibold text-indigo-700">{message}</p>}<div className="grid gap-5 xl:grid-cols-[320px_1fr]"><Card><CardContent className="p-5"><h2 className="font-bold">Receive stock</h2><div className="mt-4 space-y-3"><select className="w-full rounded-lg border border-slate-200 px-2 py-2 text-xs" value={productId} onChange={event => setProductId(event.target.value)}><option value="">Select product</option>{products.map(product => <option key={product.id} value={product.id}>{product.name}</option>)}</select><Input type="number" min="1" placeholder="Quantity" value={quantity} onChange={event => setQuantity(event.target.value)} /><Input type="number" min="0" placeholder="Cost price" value={cost} onChange={event => setCost(event.target.value)} /><Input type="date" value={expiration} onChange={event => setExpiration(event.target.value)} /><Button className="w-full" onClick={receive}>Receive stock</Button></div></CardContent></Card><Card><CardContent className="p-4"><div className="mb-3 flex items-center justify-between"><h2 className="font-bold">Stock batches</h2><Button size="sm" variant="secondary" onClick={load}><RefreshCw size={14} /></Button></div><div className="overflow-x-auto"><table className="w-full text-left text-sm"><thead className="border-b border-slate-100 text-xs uppercase text-slate-500"><tr><th className="px-3 py-3">Product</th><th className="px-3 py-3">Quantity</th><th className="px-3 py-3">Price</th><th className="px-3 py-3">Expiration</th><th className="px-3 py-3">Status</th></tr></thead><tbody>{batches.map(batch => <tr key={batch.id} className="border-b border-slate-50"><td className="px-3 py-3 font-semibold">{batch.productName}<small className="block text-xs text-slate-400">{batch.sku}</small></td><td className="px-3 py-3">{batch.quantityOnHand}</td><td className="px-3 py-3">PHP {batch.retailPrice.toLocaleString()}</td><td className="px-3 py-3 text-xs text-slate-500">{batch.expirationDate ?? '—'}</td><td className="px-3 py-3 text-xs font-bold">{batch.status}</td></tr>)}</tbody></table>{!batches.length && <p className="p-8 text-center text-sm text-slate-500">No inventory batches found.</p>}</div></CardContent></Card></div></> }

function PageIntro({ title, text }: { title: string; text: string }) { return <div className="mb-6"><p className="text-[11px] font-bold uppercase tracking-[.17em] text-indigo-600">Stock operations</p><h1 className="mt-1.5 text-3xl font-black tracking-[-.055em]">{title}</h1><p className="mt-2 text-[13px] text-slate-500">{text}</p></div> }
